/* @lc app=leetcode id=3814 lang=kotlin */ class Solution { fun lb(a: List<Int>, v: Int): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] < v) m + 1 to hi else lo to m } }.last().first fun maxCapacity(costs: IntArray, capacity: IntArray, budget: Int): Int = costs.indices.sortedBy { costs[it] }.let { ord -> ord.map { costs[it] }.let { cs -> ord.map { capacity[it] }.let { cp -> cp.runningFold(0) { a, b -> maxOf(a, b) }.let { pm -> cs.indices.maxOf { i -> if (cs[i] >= budget) 0 else cp[i] + pm[minOf(i, lb(cs, budget - cs[i]))] } } } } } }